<?php
require __DIR__.'/lib.php';require_login();try{$path=rf_evidence_path($_GET['event']??0);$mime=(new finfo(FILEINFO_MIME_TYPE))->file($path);if(!in_array($mime,['application/pdf','image/png','image/jpeg'],true))throw new Exception('Unsupported attachment.');header('Content-Type: '.$mime);header('X-Content-Type-Options: nosniff');header('Cache-Control: private, no-store');header('Content-Disposition: inline; filename="Return_Attachment.'.strtolower(pathinfo($path,PATHINFO_EXTENSION)).'"');readfile($path);}catch(Throwable $e){http_response_code(403);echo e(safe_error_message($e));}
